#!/bin/sh
# Sign a release artifact or the managed rule set with minisign.
#
# The detached signature is written next to the artifact as
# `<artifact>.minisig` and must be published with it. The secret key is never
# read from the repository: pass its path explicitly (a key generated by
# scripts/generate-signing-keys.sh lives under ~/.config/kunato/keys).
set -eu

[ $# -eq 2 ] || {
    echo "usage: $0 <secret-key> <artifact>" >&2
    exit 2
}
key=$1
artifact=$2

command -v minisign >/dev/null 2>&1 || {
    cat >&2 <<'MSG'
minisign is required. Install it with:
    sudo apt-get install -y minisign
or build it from https://github.com/jedisct1/minisign
MSG
    exit 1
}
[ -f "$key" ] || {
    echo "secret key not found: $key" >&2
    exit 1
}
[ -f "$artifact" ] || {
    echo "artifact not found: $artifact" >&2
    exit 1
}

# minisign's default prehashed signature (ED) and the plain form (Ed) are both
# verified by Kunato.
minisign -S -s "$key" -m "$artifact" -x "$artifact.minisig" \
    -t "$(basename "$artifact") $(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "signed $artifact -> $artifact.minisig"
